quests[13440] = { id = 13440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz in der boreanischen Tundra!", sourceObjectiveStatus = "unverified-source-field" }
