quests[13475] = { id = 13475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Ehre" }
quests[13476] = { id = 13476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Ehre", description = "Der Horde in einer der größten Schlachten gegen die Allianz zu dienen, ist das Ausschlaggebende für große Ehre! Die Wenigen jedoch, die der Horde auf ALL unseren aktiven Schlachtfeldern gedient haben, sind unsere wahren, großen Kämpfer. Unsere Gegner sollen besiegt werden, aber nicht mittels vereinzelter Gefechte, sondern durch einen gut koordinierten Krieg.\n\nGeht und schmettert die Allianz an allen Fronten nieder! Für Ehre! Für die Horde!", sourceObjective = "Bringt ein Ehrenabzeichen jedes Schlachtfelds zu einem Kriegshetzer der Horde in einer der Hauptstädte, Shattrath, Dalaran oder Tausendwinter.", sourceObjectiveStatus = "unverified-source-field" }
quests[13477] = { id = 13477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsames Bestreben" }
quests[13478] = { id = 13478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsames Bestreben", description = "Wir kämpfen nicht mehr in vereinzelten Schlachten gegen die Horde, <Junge/Mädel>.\n\nDer gesamte Sieg an einer Front bedeutet der Horde die Ressourcen abzusprechen, die sie ansonsten in einer anderen Schlacht gegen uns verwenden würden. Ebenso könnte das Aufgeben in was auch immer für einer Schlacht unserem Gegner andernorts in der Welt einen Vorteil verschaffen.\n\nDie Allianz benötigt mehr Kämpfer mit diesem globalen Verständnis... wirklich bewährte Veteranen! {name}, kommt zu mir zurück, wenn Ihr Euch gegen die Horde auf all unseren aktiven Schlachtfeldern bewährt habt.", sourceObjective = "Bringt ein Ehrenabzeichen jedes Schlachtfelds zu einem Brigadegeneral der Allianz in einer der Hauptstädte, Shattrath, Dalaran oder Tausendwinter.", sourceObjectiveStatus = "unverified-source-field" }
quests[13479] = { id = 13479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Eiersuche", description = "Nobelgarten, das Fest des Lebens und Frühlings! Ich hoffe, die Eiersuche hat Euch Spaß gemacht, denn ich könnte die Hilfe von jemandem, der so tüchtig ist wie Ihr, gut brauchen.\n\nIch bin mir nicht sicher, welcher Art die Magie war, die für die Erschaffung der Eier eingesetzt wurde und die Druiden halten sich mit Erklärungen zurück. Vielleicht könntet Ihr während Eurer Suche ein paar Eierschalenstücke für mich mitsammeln. Den Inhalt der Eier könnt Ihr behalten; alles was ich brauche ist eine Probe des Eis selber.", sourceObjective = "Der Frühlingsernter möchte, dass Ihr 20 Eierschalenstücke besorgt.", progress = "Habt Ihr die Schalenstücke?", completion = "Exzellent, exzellent, vielen Dank! Ich werde wahrscheinlich mehr Proben brauchen, um aussagekräftige Ergebnisse zu erhalten, aber für heute habt Ihr gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13480] = { id = 13480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Eiersuche", description = "Nobelgarten, das Fest des Lebens und Frühlings! Ich hoffe, die Eiersuche hat Euch Spaß gemacht, denn ich könnte die Hilfe von jemandem, der so tüchtig ist wie Ihr, gut brauchen.\n\nIch bin mir nicht sicher, welcher Art die Magie war, die für die Erschaffung der Eier eingesetzt wurde und die Druiden halten sich mit Erklärungen zurück. Vielleicht könntet Ihr während Eurer Suche ein paar Eierschalenstücke für mich mitsammeln. Den Inhalt der Eier könnt Ihr behalten; alles was ich brauche ist eine Probe des Eis selber.", sourceObjective = "Der Frühlingssammler möchte, dass Ihr 20 Eierschalenstücke besorgt.", progress = "Habt Ihr die Schalenstücke?", completion = "Exzellent, exzellent, vielen Dank! Ich werde wahrscheinlich mehr Proben brauchen, um aussagekräftige Ergebnisse zu erhalten, aber für heute habt Ihr gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13481] = { id = 13481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst uns von hier verschwinden!", description = "Das Licht ist mir hold. Dieser wahrgewordene Alptraum hat mich noch nicht erledigt, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt zu entkommen.\n\nAlleine werde ich es nicht schaffen, {class}, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", sourceObjective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Bruder Keltan an Bord der Orgrims Hammer Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13482] = { id = 13482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst uns von hier verschwinden", description = "Das Licht ist mir hold. Dieser wahrgewordene Alptraum hat mich noch nicht erledigt, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt zu entkommen.\n\nAlleine werde ich es nicht schaffen, mein Kind, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", sourceObjective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Absalan dem Frommen an Bord der Himmelsbrecher Bericht.", completion = "Dem Licht sei Dank. Ich glaubte, Vater Kamaros sei tot oder ihm sei noch Schlimmeres zugestoßen. Eure Tapferkeit und Euer Mitgefühl haben dazu geführt, dass ein wichtiger Verbündeter zum Argentumkreuzzug zurückkehren konnte. Ihr habt meinen Dank und den des Kreuzzugs.", sourceObjectiveStatus = "unverified-source-field" }
quests[13483] = { id = 13483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingsernter", description = "Falls Ihr nach Arbeit sucht - ich habe gehört, dass es in den Siedlungen in der Nähe großer Städte - in Klingenhügel, in Brill, im Dorf der Bluthufe und am Falkenplatz - Magier geben soll, die Eiersucher anstellen, die ihnen bei ihren Forschungen helfen. Ich kenne keine Einzelheiten, aber die werden sie Euch sicher gerne geben.", sourceObjective = "Sprecht mit einem Frühlingsernter in Klingenhügel, in Brill, im Dorf der Bluthufe oder auf dem Falkenplatz.", completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[13484] = { id = 13484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingssammler", description = "Falls Ihr nach Arbeit sucht - ich habe gehört, dass es in den Siedlungen in der Nähe großer Städte - Goldhain, Kharanos, Dolanaar und Azurwacht - Magier geben soll, die Eiersucher anstellen, die ihnen bei ihren Forschungen helfen. Ich kenne keine Einzelheiten, aber die werden sie Euch sicher gerne geben.", sourceObjective = "Sprecht mit einem Frühlingssammler in Goldhain, Kharanos, Dolanaar oder Azurwacht.", completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[13485] = { id = 13485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme der Boreanischen Tundra.", sourceObjectiveStatus = "unverified-source-field" }
