quests[13501] = { id = 13501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13502] = { id = 13502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Korb bekommen!", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", sourceObjective = "Der Nobelgartenverkäufer möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokoladen wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13503] = { id = 13503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Korb bekommen!", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", sourceObjective = "Der Nobelgartenhändler möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokolade wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13504] = { id = 13504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiter der Splitterspeere", description = "In den Ruinen im Norden und Nordosten gibt es eine große Schar von Splitterspeertrollen, die dort herumstöbern. Ich vermute, sie suchen nach magischen Artefakten, aber keiner unserer Späher kann von nennenswerten Funden in ihren Ausgrabungsstätten berichten. Vielleicht treiben sie ja auch einfach nur ihre Kriegsmaschinerie voran.\n\nEines ist aber recht sicher: Arbeitermangel würde ihren Angriff schwächen, also verpassen wir ihnen einen Arbeitermangel. Seid Ihr dabei?", sourceObjective = "Tötet 10 Arbeiter der Splitterspeere.", completion = "Gute Arbeit. Vielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13505] = { id = 13505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Hochgeborenen", description = "Es gibt überall an der Dunkelküste ähnliche Ruinen wie diese und viele von ihnen werden von geplagten Geistern der Hochgeborenen heimgesucht. Aus Rücksicht auf ihre verfluchten Seelen haben wir uns bisher damit zurückgehalten, die Ruinen nach Artefakten zu durchsuchen, aber solche guten Vorsätze müssen im Angesicht dieser neuen Bedrohung durch die Trolle aufgegeben werden.\n\nBitte bergt sämtliche Artefakte, auf die Ihr stoßt, während Ihr den Schildwachen bei der Erfüllung ihrer Ziele in den Ruinen helft, und bringt sie zu mir zurück. Ich würde gern so viele retten, wie ich kann.", sourceObjective = "Erhaltet 8 Relikte der Hochgeborenen.", progress = "Konntet Ihr irgendwelche Artefakte bergen?", completion = "Perfekt! Habt vielen Dank. Ich würde nur sehr ungern noch mehr Zeugnisse unserer Kultur an den Krieg verlieren - viel zu Vieles mussten wir schon opfern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13506] = { id = 13506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zur Sorge", description = "Hierbei scheint es sich um Befehle zu handeln, die von einem Vorgesetzten im Kriegslager der Splitterspeere an die Vorarbeiter in den Ruinen geschickt wurden. Der Großteil der Dokumente ist von unwesentlichem strategischen Wert, aber ein paar Zeilen fallen Euch auf.\n\n\"Wir haben noch eine Nachtelfenspionin aufgegriffen. Sie wurde zum Lager gebracht, um ihr unter Folter mehr Informationen zu entlocken. Haltet nach weiteren Spionen Ausschau - wir können es uns nicht leisten, dass unsere Operation hier aufgedeckt wird.\"\n\nLeutnant Sternenhauch möchte diese Informationen sicher sehen.", sourceObjective = "Bringt die Splitterspeerbefehle zu Leutnant Morra Sternenhauch in den Ruinen von Mathystra.", progress = "Ja, {class}?", completion = "\"Noch einen\"? Sie haben also mehr als einen. Ich werde keinen meiner Leute der Folter überlassen, wir müssen schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[13507] = { id = 13507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwehrt ihnen die Arbeit", description = "Im Norden haben die Splitterspeere ein Kriegslager, in dem sie ihre Katapulte bauen. Das Lager wird von einigen ihrer Mystiker bewacht, aber ich habe auch erste Berichte erhalten, dass Orcs und Tauren ebenfalls gesichtet wurden.\n\nIch möchte keine Spekulationen anstellen, was das bedeuten könnte, aber ich möchte sehr wohl, dass Ihr Euch auf den Weg macht und sie tötet, bevor sie noch weitere Angriffe auf unsere Schildwachen starten können.", sourceObjective = "Tötet 6 Vollstrecker der Horde und 6 Mystiker der Splitterspeere.", completion = "Ausgezeichnete Arbeit. Eine weitere Bedrohung, über die wir uns etwas weniger Sorgen machen müssen. Wir werden unseren Angriff fortsetzen, während sie noch desorientiert sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13508] = { id = 13508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Reaktion", description = "Wir haben vor ein paar Tagen den Kontakt mit einer meiner Späherinnen verloren. Ich hielt sie für tot, aber anscheinend wurde sie nur gefangengenommen. Den Trollen nach haben sie aber zwei Gefangene... Die einzige weitere Person, die in Frage kommt, ist Alanndarian Nachtweise, eine Zivilistin, die sich gestern Vormittag gegen meinen Rat in der Gegend aufgehalten hat.\n\nDie Splitterspeere haben im Norden ein Kriegslager aufgeschlagen - dorthin werden sie mit an Sicherheit grenzender Wahrscheinlichkeit alle Gefangenen gebracht haben. Macht sie ausfindig und befreit sie, wenn Ihr könnt.", sourceObjective = "Findet die gefangenen Nachtelfen im Kriegslager der Splitterspeere.", completion = "<Alanndarian sieht äußerst blass aus, doch schwache Atemzüge bezeugen, dass noch Leben in ihr steckt.>\n\nIhr seid hier, um... mich zu retten? Etwas später... als ich gehofft hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13509] = { id = 13509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorräte", description = "Die Trolle sammeln ihre Truppen und Vorräte in ihrem Kriegslager im Norden. Sie werden von dort fast mit Sicherheit ihren Angriff auf Lor'danel starten, sobald sie sich bereit fühlen. Es sollte nicht lange dauern, dieses Gesindel in die Flucht zu schlagen, ich bin jedoch dagegen, unnötige Risiken einzugehen.\n\nIch möchte, dass Ihr Euch einen Weg in das Kriegslager erkämpft und alle Vorräte in Brand steckt, die Ihr finden könnt. Dieser Rückschlag sollte uns einige Zeit verschaffen, bis sie einen Gegenangriff starten können.", sourceObjective = "Zerstört 12 Vorratskisten der Splitterspeere.", completion = "Ausgezeichnete Arbeit. Das sollte sie ein wenig aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13510] = { id = 13510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtzeitige Ankunft", description = "Schön Euch zu sehen. Ich habe mich nicht darauf gefreut, das Gleiche durchzumachen wie Alanndarian, also ist mir Eure Rettung sehr willkommen.\n\nIch konnte den Anführer der Trolle entdecken, bevor man mich fasste. Ich dachte, ich hätte die perfekte Gelegenheit, ihn auszuschalten, aber er wird von einer Art magischem Schild geschützt. Morra muss davon in Kenntnis gesetzt werden, bevor sie ihren Angriff startet, aber zuerst müssen wir hier verschwinden.\n\nHelft mir zum Dock - ich werde Lor'danel über den Wasserweg erreichen und Ihr könnt die Informationen zu Morra zurückbringen.", sourceObjective = "Bringt Schildwache Aynasha in Sicherheit.", completion = "Eine Art Schild, sagt Ihr? Dagegen haben wir vielleicht ein Mittel. Balthule ist ein Einfall gekommen, wie man jegliche Schutzzauber ihrer Schamanen durchbrechen kann. Vielleicht funktioniert das auch damit. Danke, dass Ihr Aynasha gerettet und mir diese Informationen überliefert habt - das könnte womöglich unseren Kampf hier entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13511] = { id = 13511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbitterter Wunsch", description = "Morra schickt Euch? Ich hätte auf sie hören sollen - es ist wohl zu einfach, Trolle nicht ernst zu nehmen.\n\n<Alanndarian lacht leise in sich hinein.>\n\nDafür ist es jetzt ohnehin viel zu spät. Wir sind jetzt sterblich... dies ist das Schicksal, dem wir früher oder später erliegen werden. Ich habe Zeit genug gehabt, mich damit abzufinden.\n\nEine Bitte habe ich jedoch... tötet den Folterer, der mir das hier angetan hat. Sie nennen ihn Rit'ko... Ihr könnt ihn weiter vorne bei der anderen Gefangenen finden.\n\n<Alanndarian lächelt schwach, zuckt dann vor Schmerz zusammen und sinkt wieder zu Boden.>", sourceObjective = "Tötet Rit'ko, den Folterer der Splitterspeere.", completion = "Alanndarian ist also tot. Das bedrückt mich sehr, kommt aber nicht gänzlich unerwartet. Ich erwarte von diesen Wilden keine Gnade und werde ihnen auch keine zuteilwerden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13512] = { id = 13512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategische Schläge", description = "Der Bestie den Kopf abzuschlagen hat keinen Sinn, wenn es einen zweiten Kopf gibt, der ihn ersetzen kann. Bevor wir ihren Anführer ausschalten können, müssen wir die Unteranführer töten, die das Machtvakuum füllen würden. Momentan werden sie nicht so gut beschützt und Ihr solltet sie ohne weitere Unterstützung besiegen können.\n\nNehmt diesen Dryadenspeer und spürt sie auf. Das Gift an seiner Spitze sollte ihre Zaubersprüche verlangsamen. Meine Späher berichten mir, dass einer von ihnen in der Wasserkammer in den Ruinen im Osten ist und der andere wurde hinter den Überresten des Turmes im Südwesten gesichtet.", sourceObjective = "Tötet Sheya Sturmwirker und Lorenth Donnerruf.", completion = "Ihr habt eine Menge Talent bewiesen für jemanden, der noch so jung ist. Gute Arbeit. Offenbar steht uns die letzte Schlacht kurz bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[13513] = { id = 13513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zurück", description = "Ich arbeite bereits an einem Mittel, um ihre Schutzzauber zu überwinden. Mit einem Fokus, der auf ihren Mächten beruht, und etwas Druidenmagie sollten wir in der Lage sein, ihre Schilde zu durchbrechen.\n\nSpürt ihre Schamanen im Osten und Südosten auf und beschafft einige ihrer Amulette. Ich werde sie vorbereiten und einen Pfeil verzaubern, den Ihr Sandrya Mondsturz für den Angriff überbringen könnt.", sourceObjective = "Erhaltet 6 Amulette der Splitterspeere.", progress = "Habt Ihr die Amulette bei Euch?", completion = "Diese Amulette sind genau das, was ich brauche. Ich werde sie für Sandrya vorbereiten - man wird Euch sicher gleich beauftragen, Euch mit ihr zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13514] = { id = 13514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Urtume", description = "Seid Ihr hier, um Euch dem Angriff anzuschließen? Wenn Ihr nach Sandrya Mondsturz sucht, findet Ihr sie in der Höhle am Ende dieses Tals, wo sie den Angriff auf den Anführer der Splitterspeere leitet.\n\nWo Ihr schon hier seid, könnten wir allerdings auch Eure Hilfe beim Zusammentreiben des restlichen Stammes brauchen. Zieht mit einem der rachsüchtigen Beschützer los und sorgt dafür, dass auch das letzte Gebäude zerstört und der Stamm bis auf den letzten Troll ausgelöscht wird. Wir wollen doch nicht, dass sie versuchen, sich an uns zu rächen, wenn wir nicht darauf gefasst sind, oder?", sourceObjective = "Benutzt einen rachsüchtigen Beschützer um 30 Trolle der Splitterspeere zu töten und 6 Gebäude der Splitterspeere zu zerstören.", completion = "Ihr habt Euch dort oben hervorragend geschlagen! Wir können von Glück reden, Euch bei uns zu haben.\n\nIch habe noch keine Nachricht über ihren Anführer erhalten. Wenn Ihr noch nicht mit Sandrya in der Höhle am Ende des Tals gesprochen habt, solltet Ihr das unbedingt nachholen, bevor Ihr wieder aufbrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13515] = { id = 13515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Bedrohung", description = "Auf uns warten ihr Anführer und seine Leibwache. Meine Schildwachen sind bereit, seine Leibwächter auszuschalten. Wir warten nur auf diesen Pfeil, um das Schicksal ihres Anführers zu besiegeln.\n\nLasst es mich wissen, wenn Ihr bereit für den Angriff seid. Sobald meine Schildwachen die Höhle stürmen, werde ich den Schild des Anführers zertrümmern und wir werden ihm gemeinsam entgegentreten. Schlagt geschwind zu und wir können diese Bedrohung für unsere Ländereien hier und heute beenden.\n\nWir warten nur auf Euch - sprecht mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Sandrya Mondsturz, um den Angriff zu starten, und helft ihr dann dabei, Jor'kil den Seelenreißer zu töten.", completion = "Wir stehen tief in Eurer Schuld für alles, was Ihr getan habt, um diese Schlacht zu einem glücklichen Ende zu bringen.\n\nEs geschieht nicht oft, dass wir einen derartig eindeutigen Sieg davontragen können, aber wie es scheint, steht hinter dieser Verschwörung mehr als nur der Stamm der Splitterspeere. Wenn Ihr seine Leiche noch nicht nach Informationen durchsucht habt, solltet Ihr dies tun, bevor Ihr weiterzieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13518] = { id = 13518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Welle Überlebender", description = "Für Laird ist es zu spät, er hat es nicht mehr rechtzeitig geschafft.\n\nDie letzte Welle Nachtelfen aus Auberdine hat vor ein paar Stunden versucht zu entkommen. Sie sind in ihrem alten Zuhause geblieben und haben sich an die Hoffnung geklammert, dass es gerettet werden kann, aber offenbar mussten sie sich letzten Endes den Naturgewalten beugen. Ich befürchte, dass viele von ihnen es nicht schaffen werden, so wie Laird.\n\nEilt Euch. Geht zur Küste im Westen hinunter und macht so viele Überlebende ausfindig, wie Ihr könnt. Wir schicken Schildwachen und Hippogryphen, aber jeder Augenblick zählt - wir müssen wissen, wer überleben könnte.", sourceObjective = "Macht alle überlebenden Flüchtlinge von Auberdine ausfindig.", completion = "Ich danke Euch, {class}. Manche von ihnen hätten es ohne Eure Hilfe nicht geschafft.\n\nWir werden die Verwundeten ins Hauptgebäude bringen, sobald alle sicher in der Stadt angekommen sind. Vielleicht könnt Ihr uns später dort aufsuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13519] = { id = 13519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenhammer", description = "Eine Gruppe von Schattenhammerkultisten hat südwestlich von hier Lager aufgeschlagen. Sie stellen eine Armee von Wasserelementaren zusammen, die gegen Lor'danel eingesetzt werden könnte.\n\nIhr Anführer, der Hochkultist Azerynn, hat einen Pakt mit den dunklen Göttern geschlossen, die seinem Kult Macht über die Elemente gewähren. Kümmert Euch darum, bevor es zu spät ist, {name}.\n\nDer Kataklysmus hat die Elemente verwirrt... es ist nur eine Frage der Zeit, bis sie genug Elementare haben, um unsere Verteidigung zu übermannen.", sourceObjective = "Tötet Hochkultist Azerynn und 10 Fanatiker des Schattenhammers im Lager des Schattenhammers.", completion = "Ihr habt gute Arbeit geleistet, {name}. Der Schattenhammer ist ein gefährlicher Kult. Die Gefahr, die sie darstellen, zu unterschätzen, wäre die Tat eines Narren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13520] = { id = 13520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen der Meere", description = "Gut, Euch zu sehen. Dank Euch sind unsere Verwandten sicher nach Hause gekommen und ich hege Hoffnung, dass Ihr uns auch weiterhin helfen könnt.\n\nIhre Wunden werden so schlimm sein wie die von Laird - jeder einzelne wurde an der Küste arg mitgenommen und von den Elementaren angegriffen. Ich tue, was ich kann, aber es scheint, als hätten die Elementare ein Gift, das die Wundheilung einschränkt. Ich hoffe eine Salbe herstellen zu können, aber dazu benötige ich Sekret von Muschelmuskeln, die an der Küste zu finden sind. Könnt Ihr mir helfen?", sourceObjective = "Sammelt 16 verkrustete Muschelmuskeln.", progress = "Habt Ihr die Muschelmuskeln? Ich fürchte, wir haben nicht mehr viel Zeit.", completion = "Die sind ideal. Ich danke Euch vielmals!\n\nIch gehe davon aus, dass sie Euch selbst danken wollen, falls sie wieder zu Kräften kommen. Vielleicht könnt Ihr ja später noch einmal hierherkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13521] = { id = 13521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 413", description = "Seid gegrüßt!\n\nIch helfe Tharnariun dabei herauszufinden, wo der Ursprung der Verderbnis der Tierwelt in der Gegend liegt. Ich habe ein Gerät in der Umgebung aufgestellt, das Tierteile und mögliche Verderbniserreger analysieren kann. Wenn Ihr mir ein paar gute Proben besorgen könnt, so werden wir schnell herausfinden, was es mit der Verderbnis auf sich hat.\n\nDas erste Gerät ist die Dröhnkiste 413. Sie steht am Strand östlich der Stadt. Besorgt das Fleisch der verderbten Gezeitenkriecher in der Nähe und bringt es zur Dröhnkiste, damit wir es analysieren können.", sourceObjective = "Sammelt 4 Proben verderbtes Gezeitenkriecherfleisch und bringt es zur Analyse zur Dröhnkiste 413.", progress = "<Dröhnkiste 413 dröhnt Euch erwartungsvoll entgegen.>", completion = "<Das Gerät knattert vor sich hin und plötzlich ertönt Hexknalls statische Stimme.>\n\nWunderbar! Ich hoffe, Ihr habt nicht zu viele getötet. Wir wollen sie nicht dem Aussterben nahe bringen, sondern nur schnell herausfinden, wo die Verderbnis herkommt! Ich fahre jetzt mit der Analyse fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[13522] = { id = 13522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Wasser", description = "Ein paar der Überlebenden des letzten Angriffs von Auberdine versuchen noch immer, an die Küste und in Sicherheit zu gelangen. Wir haben vor weniger als einer Stunde erst erfahren, dass sie kommen. Ich wünschte, wir hätten mehr Vorwarnzeit gehabt...\n\nAn der Küste westlich von hier wimmelt es von bösartigen kleinen Wasserelementaren. Wir müssen sie beseitigen, wenn die Überlebenden es bis nach Lor'danel schaffen sollen. Macht Euch sofort auf den Weg und tötet jeden Elementar, den Ihr finden könnt.", sourceObjective = "Tötet 8 widerwärtige Gischte.", completion = "Wir sind Euch für Eure Anstrengungen sehr dankbar. Seit dem Kataklysmus sind die Elementare außer Kontrolle. Wir hegen wenig Hoffnung, Auberdine zurückzuerobern, ohne vorher die Elementare auszulöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13523] = { id = 13523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht über die Gezeiten", description = "Sorgt Euch nicht um mich. Meine Wunden sind tief und bald wird mich der Tod ereilen.\n\nNun liegt alles in Euren Händen... Ihr müsst den Schattenhammer aufhalten.\n\nDie alten Götter, die von ihnen verehrt werden, haben ihnen Macht über die ruhelosen Wassergeister gewährt... diese Macht ist heikel. Kanalisiert Elunes Präsenz durch diese Kugel, sobald die Elementare besiegt sind.\n\nVerwendet die Macht Elunes, um die Geister für immer zu verbannen.", sourceObjective = "Wendet die Kugel von Elune an den Überresten von 6 wütenden Gezeitengeistern an.", completion = "Ihr habt es geschafft... nicht alles war vergebens...\n\nMeine Zeit ist gekommen. Geht nun, {name}. Möge Elune Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13524] = { id = 13524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Silberwasser", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!", sourceObjective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13525] = { id = 13525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist mit den Furbolgs der Schwarzfelle los?", description = "Unsere Vorfahren lebten schon seit Generationen friedlich neben den Furbolgs der Schwarzfelle. In letzter Zeit aber ist der Kontakt zu den Siedlungen abgebrochen, die sich tiefer im Wald befinden. Eines ihrer größeren Dörfer, Schwarzfellfeste, befindet sich südlich von hier.\n\nReist dorthin und findet den Ältesten Brolg. Fragt ihn, warum sich sein Volk von uns zurückgezogen hat und bietet Eure Hilfe an, wenn es ihrer bedarf.", sourceObjective = "Sprecht mit dem Ältesten Brolg in der Schwarzfellfeste.", completion = "Was verschlägt Euch hier her, Außenseiter?\n\n<Ihr erzählt dem Ältesten, dass Foriel Rundblatt vom Hain der Uralten Euch geschickt hat. Der Älteste scheint sich ein wenig zu beruhigen.>\n\nDer Elf hat Recht. Die Streitmächte aus Teufelswald sind bis zur Dunkelküste vorgedrungen und haben mein Volk krank gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13526] = { id = 13526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bärenklau", description = "Die garstigen Satyrn aus Teufelswald haben begonnen, ihr Gift an die Dunkelküste, in unser Land zu bringen. Die Verderbnis verdirbt das Land und verdreht dessen Bewohner - auch mein Volk.\n\nUnsere Magie alleine reicht nicht aus, um sie wieder gesunden zu lassen. Es gibt allerdings eine Pflanze namens Bärenklau, mit der wir Fieber senken und die Schwachen stärken. Mit der Hilfe dieser Pflanze könnte auch der Einfluss der Satyrn geheilt werden. Ihr findet die Pflanze in der Wildnis in der Nähe des Dorfes.", sourceObjective = "Bringt 8 Stängel Bärenklau zum Ältesten Brolg in der Schwarzfellfeste.", progress = "Habt Ihr den Bärenklau?", completion = "Die Stängel sind kümmerlich und schwach, aber mehr haben wir nicht. Die Verderbnis verbreitet sich schnell und selbst die Pflanzen bleiben nicht verschont.", sourceObjectiveStatus = "unverified-source-field" }
quests[13527] = { id = 13527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über Geschmack lässt sich nicht streiten", description = "<Das Gerät rauscht ein paar Augenblicke lang, bevor Hexknalls Stimme ertönt.>\n\nInteressant! Der Ursprung der Verderbnis kommt definitiv von einer externen Quelle - was mich weniger verwundert - aber es scheint, als wurde sie durch das Essen verderbter Nahrung übertragen, ein großes Säugetier wahrscheinlich, ich würde auf einen Bären tippen.\n\nSucht den Strand nach dem Kadaver des Bären ab. Östlich von hier würde es am meisten Sinn ergeben, an der Seite des Strandes, die zum Landesinneren zeigt. Bringt mir eine Probe von seinem Fleisch.", sourceObjective = "Erhaltet die Probe eines faulenden Bärenkadavers östlich von Dröhnkiste 413.", progress = "Willkommen zurück! Habt Ihr den Kadaver gefunden und ihm eine Probe entnehmen können?", completion = "Das sieht eindeutig nach dem Zeug aus, das sie gegessen haben. Lasst mich das genauer anschauen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13528] = { id = 13528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 723", description = "Wir konnten noch an ein paar anderen wilden Tieren eine Infektion feststellen. Es sind sogar gute Neuigkeiten, dass die Kriecher sich an den Bären angesteckt haben - hoffentlich lassen sich alle Fälle auf diese eine Quelle zurückführen. Jetzt müssen wir unsere Aufmerksamkeit den Bären widmen.\n\nDröhnkiste 723 ist in der Nähe der Wasserfälle östlich von hier. Es ist keine schöne Arbeit, aber sie ist nötig: ich brauche für die Analyse frische Bäreneingeweide für die Dröhnkiste. Mit weiteren Informationen können die nächsten Schritte leichter bestimmt werden.", sourceObjective = "Sammelt 6 Proben verderbte Eingeweide eines Distelbären und bringt sie zu Dröhnkiste 723 für eine Analyse.", progress = "<Dröhnkiste 723 dröhnt Euch erwartungsvoll entgegen.>", completion = "<Es rauscht statisch, bevor Hexknalls verzerrte Stimme ertönt.>\n\nWir bekommen gerade die Ergebnisse. Wir sollten jeden Augenblick mehr Informationen darüber erhalten, wie die Bären sich die Verderbnis eingefangen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13529] = { id = 13529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ursprung der Verderbnis", description = "Ich habe mich auf den Weg gemacht, als ich die Neuigkeiten von Hexknall gehört habe. Ich weiß jetzt, wer hinter allem steckt: Zenn Faulhuf.\n\nEr kam von Teldrassil hierher, nachdem er von dort für das Wirken pervertierter Magie verjagt worden war. Die Art von Verderbnis, die er anwendet, ist in meinen Reihen nicht willkommen und es scheint als sei er dieses Mal einen Schritt zu weit gegangen. Vielleicht hat er es aus Rache getan.\n\nZenn wurde zu lange akzeptiert und es ist an der Zeit, dass wir diese Bedrohung all dessen, was natürlich ist, beseitigen. Tötet Zenn und seine Diener. Sucht mich dann in Lor'danel auf.", sourceObjective = "Tötet Zenn Faulhuf und 8 üble Grells in der Klippenquellgrotte.", completion = "Es ist vollbracht. Ich danke Euch. Ich hoffe nur, dass die Wildtiere nach seinem Tod etwas mehr Frieden finden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13537] = { id = 13537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Barsch", description = "Nach all dem Bootfahren und Bauen bin ich erschöpft... und hungrig. Wisst Ihr, worauf ich Lust habe? Fisch. Fisch klingt für mich jetzt unfassbar gut.\n\nDunkelküste ist für Barsch bekannt. Wenn Ihr mir welchen fischt, werde ich dafür sorgen, dass es sich für Euch lohnt.", sourceObjective = "Benutzt Eure Angelfertigkeit, um 4 Dunkelküstenbarsche zu erhalten.", progress = "<Ihr hört Johnathans Bauch knurren, als Ihr Euch nähert.>\n\nBesser hätten Worte es nicht ausdrücken können.", completion = "Es scheint, als sei Angeln etwas, das Euch liegt. Mein Bauch ist für dieses Geschenk sehr dankbar.\n\nIch glaube, Ihr könnt mit dieser Angelrute mehr anfangen als ich. Nehmt sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[13538] = { id = 13538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage aus dem Süden", description = "Die drei Türme südlich des Tausendwinterflusses entziehen der Festung Energie!\n\nMacht den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm dem Erdboden gleich und erstattet mir dann Bericht. Denkt dran, nur Belagerungsmaschinen können einen Turm beschädigen, deshalb müsst Ihr sie gut vor der Horde beschützen!", sourceObjective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Ahbramis in Tausendwinter zurück.", completion = "Ich habe die Explosion bis hier gehört! Gute Arbeit - wir haben schon damit begonnen, die Energie in das Relikt der Titanen umzuleiten, um eine Superaufladung für unsere eigenen Truppen zu ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13539] = { id = 13539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstürzende Turmbauten", description = "Während die Allianz gegen unsere Türen hämmert, schaut ein wahrer Taktiker über das Offensichtliche hinaus.\n\n\"Greif ihn an, wo er unvorbereitet ist, erscheine, wo du nicht erwartest wirst.\"\n\n{name}, überquert den Tausendwinterfluss und macht einen der drei Türme im Süden dem Erdboden gleich. Unsere Hexenmeister berichten, dass die Türme Energie abziehen, die wir benutzen könnten, um unsere eigenen Truppen zu stärken.\n\nKehrt zu mir zurück, sobald Ihr einen Turm zerstört habt.", sourceObjective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Kilrath in Tausendwinter zurück.", completion = "Und nun, um den Feind zu vernichten, muss der Zorn unserer Truppen geweckt werden. Um den Vorteil darin zu sehen, den Feind zu besiegen, müssen sie ihre Belohnungen erhalten. Ich hoffe, dass dies hier Euren Dienst an der Horde ausreichend entlohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13542] = { id = 13542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen den Wind", description = "Wenn wir die Ruinen von Auberdine aus den Händen des Schattenhammers zurückerlangen möchten, so müssen wir uns dauerhaft um die Elementare kümmern, die sie beschworen haben.\n\nHier kommt Ihr ins Spiel.\n\nIch erwarte nicht, dass Ihr die Stadt alleine einnehmt, aber während wir hier oben heilen, könnt Ihr sie für uns schonmal weichklopfen.\n\nUm mit den rasenden Zyklonen auf lange Sicht fertig zu werden, müsst Ihr Euch nach Westen begeben, sie töten, ihre Armschienen an Euch nehmen und sie in den Mondbrunnen werfen. Das wird die Armschienen zerstören und verhindern, dass die Elementare wieder beschworen werden können.", sourceObjective = "Benutzt den Mondbrunnen in den Ruinen von Auberdine, um 8 Armschienen des rasenden Zyklons zu zerstören.", completion = "Ich kann Euch gar nicht genug danken, {name}. Nun haben wir eine realistische Chance, die Ruinen zurückzuerobern, sobald wir uns erholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13543] = { id = 13543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Hammer zu Brechen...", description = "Ich bin über die Ruinen von Auberdine geflogen, um das Gebiet auszukundschaften. Drei Schattenhammerkultisten dort sind für die Elementare verantwortlich, die die zerstörte Stadt eingenommen haben.\n\nBegebt Euch zu den Ruinen westlich von hier. Sucht und besiegt Wolkenzähmerin Wildmähne, Windmeister Tzu-Tzu und den Himmelsfürst Braax.\n\nWenn sie aus dem Weg geschafft sind, werden Schildwache Selarin und ihre Truppen eine Chance haben, ihre Heimat zurückzuerobern.", sourceObjective = "Tötet Wolkenzähmerin Wildmähne, Windmeister Tzu-Tzu und Himmelsfürst Braax.", completion = "Ohne dass die Drei hier weiter Elementare anlocken, wird es in den Ruinen von Auberdine weitaus weniger von ihnen geben.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13544] = { id = 13544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bärensegen", description = "Bevor der Bärenklau verwendet werden kann, um die Betroffenen zu reinigen, müssen wir ihn dafür vorbereiten und segnen. Nördlich von unserem Dorf ist ein Weitschreiter namens Flinkfuß zu finden. Um das Bündel zu vervollständigen, brauchen wir seine Schwanzfedern.\n\nBringt die Schwanzfedern und das Bärenklaubündel zur uralten Bärenstatue in den Ruinen beim Hain der Uralten, noch weiter nördlich als Flinkfuß.\n\nFügt am Schrein die Schwanzfedern dem Bärenklau hinzu und erhaltet den Segen des Bärengeists.", sourceObjective = "Bringt das gesegnete Kräuterbündel zum Ältesten Brolg in Schwarzfellfeste.", progress = "Wart Ihr bei der uralten Bärenstatue?", completion = "<Der Älteste Brolg nimmt das gesegnete Bündel entgegen und betrachtet es.>\n\nDas ist genau das, was ich brauche. Der Bärengeist ist uns wohlgesinnt und es gibt doch noch Hoffnung für meine Brüder.", sourceObjectiveStatus = "unverified-source-field" }
quests[13545] = { id = 13545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befallenen reinigen", description = "Mit den vom Bärengeist gesegneten Pflanzen im Kräuterbündel können meine Brüder nun gereinigt werden. Die Verderbnis aus Teufelswald hat sie in den Wahnsinn getrieben und sie greifen jeden an, der ihnen zu nahe kommt. Ihr müsst damit rechnen, dass die Befallenen feindlich auf Euch reagieren werden, bis Ihr die Geister der Verderbnis getötet habt, die sie verfolgen.\n\nKehrt zu mir zurück, wenn Ihr meine Brüder von der Verderbnis befreit habt.", sourceObjective = "Der Älteste Brolg möchte, dass Ihr das gesegnete Kräuterbündel benutzt, um 7 Furbolgs der Schwarzfellfeste zu läutern und die Geister der Verderbnis, die sie in den Wahnsinn treiben, tötet.", completion = "Ihr habt gute Taten vollbracht. Mein Volk beginnt, sich von dem Wahnsinn zu lösen. Wenn der Ursprung der Verderbnis jedoch weiterhin hier ist, so werden sie bald wieder verderbt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13546] = { id = 13546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schänder", description = "Die Jadefeuersatyrn von Teufelswald haben sich ihren Weg zur Dunkelküste gebahnt und jedem Land, jedem Wasser und jeder Kreatur unterwegs die Verderbnis auferlegt. Ihr habt gesehen, was die Verderbnis mit meinem Volk und unserer Heimat angestellt hat. Wenn wir die Satyrn nicht bekämpfen, so wird unser Schicksal das Gleiche sein.\n\nIn der Höhle östlich von hier ist Sharax der Schänder zu finden, der Satyr, der für das Leiden der Schwarzfelle verantwortlich ist. Tötet ihn, {name}, und befreit uns von seinem Einfluss. Zeigt den Satyrn, dass die Schwarzfelle nicht so leicht unterzukriegen und zu verderben sind.", sourceObjective = "Der Älteste Brolg in der Schwarzfellfeste möchte, dass Ihr Sharax den Schänder tötet.", completion = "Vielen Dank, {name}. Ihr werdet von meinem Volk als Held gefeiert. Ohne Euch wären wir dem Wahnsinn und dem Tod ausgesetzt gewesen. Möge der große Bärengeist immer über Euch wachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13547] = { id = 13547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister locken", description = "Eure Freunde im Flüchtlingslager sind sich der tatsächlichen Gefahr nicht bewusst, welche die Schattenhammerkultisten bereits über die Welt gebracht haben.\n\nDamit Ihr Euch der Sache annehmen könnt, müsst Ihr zuerst Hilfe von den Toten aus Auberdine bekommen.\n\nSucht in den Ruinen der Stadt nach den Leichen von Thundris Windwirker, Elissa Sternenhauch, Taldan, und Caylais Mondfeder. Lockt die Geister aus ihren Körpern heraus und bringt sie zu mir.", sourceObjective = "Lockt die Geister von Thundris Windwirker, Elissa Sternenhauch, Taldan und Caylais Mondfeder.", completion = "So viel Tod und Schmerz. Und zweifellos wird es noch mehr davon geben.\n\nAlles, was ich will, ist doch nur die Umarmung der Göttin spüren, so wie die anderen.\n\nZuerst müssen wir aber versuchen, mehr Leid und Zerstörung zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13548] = { id = 13548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13549] = { id = 13549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Männchen oder Weibchen?", description = "Ich bin daran interessiert, neben den Artefakten der Drakkari auch ein paar Tiere von Zul'Drak mit mir zurück nach Zandalar zu bringen. Männchen der Frostleoparden und Eispfotenbären habe ich schon - ich brauche aber Weibchen!\n\nZu dumm, dass mein Fallensteller in einem überaus unglücklichen Unfall ums Leben kam. Wäret Ihr vielleicht dazu bereit, für ihn einzuspringen?\n\nSchläfert die Leoparden und Bären mit diesem Blasrohr ein und vergewissert Euch, dass es auch Weibchen sein werden, die Ihr dann zu mir zurückbringt, wenn Ihr so nett sein würdet. Finden könnt Ihr sie an den Altären von Rhunok, Quetz'lun und Har'koa.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr mit To'kinis Blasrohr Frostleoparden und Eispfotenbären einschläfert. Kehrt mit jeweils 3 Weibchen zu ihm zurück.", completion = "Wirklich sehr ausgezeichnete Exemplare, {name}! Sie werden mit Sicherheit für Neugierde und stundenlange Spekulationen unter meinen Kollegen zuhause sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13554] = { id = 13554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung im Dunkeln", description = "<Das Gerät spuckt ein paar zusammenhangslose Wortfetzen aus, bevor Hexknalls Stimme wiederzuerkennen ist.>\n\nNachtratten! Sie haben Nachtratten gefressen! Diese kleinen Nervensägen kommen nur von einem Ort, einer Höhle an den Klippen östlich von hier. Ihr müsst nach Nordosten gehen, um zu dem Pfad zu gelangen, der zu den Höhlen führt - sucht nach einer Öffnung unter dem Wasserfall.\n\nDie Nachtratten dort brüten entweder etwas Übles aus, oder jemand hat ihnen einen Verderbniserreger absichtlich zukommen lassen. In jedem Fall brauche ich Proben von dem Zeug!", sourceObjective = "Erhaltet 6 Proben widerlicher Schleim von den Kreaturen in der Klippenquellgrotte.", progress = "Habt Ihr das Zeug bekommen? Je früher ich an einem Heilmittel arbeiten kann, umso schneller können wir die Tiere retten!", completion = "Das sollte mehr als genug sein! Vielen Dank! Ich fange sofort an, an dem Heilmittel für dieses Übel zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13556] = { id = 13556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier für Dubra'Jin", description = "Wie geht's, Mann? Was meinst du, kannst du mir helfen? Bah'Kini braucht 'ne Menge Raptoreier, um sie Dubra'Jin zu opfern.\n\nWas denkst du denn, wieso uns die Drakkari noch nicht überrannt haben?! Ja weil Dubra'Jin uns hilft!\n\nDu musst für uns die Raptoreier sammeln - die sind hier in Gundrak bei den Bäumen. Manchmal tragen die Raptoren sie auch rum, damit sie warm bleiben.", sourceObjective = "Ha'wana in Dubra'Jin möchte, dass Ihr 12 Raptoreier von Gundrak sammelt.", progress = "Wer hätt gedacht, dass der große Dubra'Jin so viele Eier haben will? Was will der eigentlich mit denen?", completion = "Eins, zwei, drei... hehe, das wird reichen, Mann! Jetzt werden wir für 'ne ganze Weile sicher sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13557] = { id = 13557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Glücks", description = "Dieser Schlüssel scheint für die Käfige zu sein, die überall in der Klippenquellgrotte verstreut sind. Tharnariun würde sich sicher freuen, wenn Ihr die Situation nutzt, um die Nachtratten und Distelbären zu befreien, die nicht verderbt wurden und gefangen gehalten werden.", sourceObjective = "Befreit 8 unverderbte Distelbären oder unverderbte Nachtratten aus den Käfigen in der Klippenquellgrotte.", progress = "Ja, {race}?", completion = "Gut zu hören, dass Ihr ein paar der Wildtiere befreien konntet. Mit ein wenig Glück werden wir ein Heilmittel finden, bevor die Verderbnis die anderen Tiere umbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13558] = { id = 13558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner herbeirufen", description = "Aetherion ist zwar schon fast in unserer Welt, aber trotzdem können wir ihn noch ausschalten!\n\nAm Ende des Docks schwebt eine Ritualkugel. Ich möchte, dass Ihr mit ihr das Ritual vollendet und den Elementarlord aus seinem Vortex holt.\n\nVertraut mir, {name}, ich und die anderen von Euch befreiten Geister werden Aetherion extrem schwächen. Allerdings müsst Ihr ihm den letzten Stoß versetzen, um das Volk der Kaldorei aus Dunkelküste vor der Zerstörung zu retten.\n\nBringt die Essenz Aetherions zu Corvine Mondaufgang im Flüchtlingslager, damit er Bescheid weiß.", sourceObjective = "Benutzt Aetherions Ritualkugel und erhaltet Aetherions Essenz.", progress = "Ihr seid zurückgekehrt. Welche Neuigkeiten bringt Ihr mir?", completion = "Yalda? Die Geister der anderen aus den Ruinen von Auberdine?\n\n<Der Druide denkt über Eure Erlebnisse in den Ruinen nach.>\n\nIch kann mich an alle erinnern. Wir werden sie sehr vermissen, aber sie haben nun zum Wohle aller die Umarmung der Göttin gefunden.\n\nAnde'thoras-ethil, mögen Eure Schwierigkeiten geringer werden, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13559] = { id = 13559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Tribut", progress = "Gewöhnlicher Tribut war nicht gut genug für den großen Hodir, als er unter den Frostriesen wandelte.\n\nEr mag zwar nicht mehr bei uns sein, doch wir haben die Tradition beibehalten, seiner Stärke und Weisheit Tribut zu zollen. Es täte Eurem Ruf sehr gut, wenn Ihr Euch an dieser Tradition beteiligen würdet, kleiner {class}.", completion = "Die Söhne Hodirs nehmen Euren Tribut an, kleines Wesen. Ihr schreitet voran auf Eurem Weg, Euren Wert als Verbündeter zu beweisen - auf mehr als eine Art." }
quests[13560] = { id = 13560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nicht so tiefe Ozean", description = "Ihr seht sehr fähig aus!\n\nAn der Küste hier sind viele Wracks - viele alte und ein paar neue. Ich versuche schon seit einiger Zeit, mich darum zu kümmern und die wertvollen Reste besser zu nutzen, aber die Murlocs, die sich dort breitgemacht haben, haben andere Vorstellungen. Ich habe viele Abenteurer losgeschickt und keiner kam zurück.\n\nSorgt Euch nicht, ich habe meine Lektion gelernt und Euer Schicksal wird ein anderes sein. Schwimmt in Richtung Norden und sucht Gary - er wird Euch den neuen Plan erklären. Es ist ganz einfach.", sourceObjective = "Gorbold Stahlhand möchte, dass Ihr Gary aufsucht, um weitere Anweisungen zu erhalten.", completion = "Die Ablenkung hat also funktioniert? Gut! Macht Euch wegen der Schätze keine Sorgen. Ich und Gary werden uns darum kümmern, diesmal.\n\nUm ehrlich zu sein glaube ich, dass sie mich aus der Stadt verjagen würden, wenn noch mehr schief läuft und noch ein weiterer Abenteurer verloren geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13561] = { id = 13561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trost für die Hochgeborenen", description = "Ich bin nach Bashal'Aran gekommen, um den besorgten Geistern der Hochgeborenen Frieden zu gewähren, aber mit jedem Hieb scheint meine Hand sich mehr zu wehren. Wenn Ihr mir helfen wollt, so könnt Ihr Euch meiner Dankbarkeit sicher sein.", sourceObjective = "Tötet 6 verfluchte Hochgeborene und 6 zuckende Hochgeborene.", completion = "Ihr habt meinen Dank. Und auch wenn man es ihnen nicht anmerkt, den Dank der Geister der Hochgeborenen habt Ihr auch.\n\nEine sichere Reise wünsche ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13562] = { id = 13562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Flamme von Bashal'Aran", description = "In Zeiten wie diesen müssen wir innehalten und unsere Lebensweise überdenken. Wir sind nun sterblich und egal, wie sehr wir auch etwas anderes bevorzugen würden, wir verdienen den Platz, den wir nun in dieser Welt einnehmen.\n\nBashal'Aran, einst die Stadt unserer Vorfahren, ist nun die Heimat ihrer verfluchten Geister. Ihr findet Bashal'Aran, wenn Ihr der Straße in Richtung Süden folgt. Wir hatten Hoffnung gehegt, Rettung zu finden, aber wir haben sie zu lange leiden lassen. Es ist an der Zeit, die letzte Flamme von Bashal'Aran auszulöschen.", sourceObjective = "Löscht die letzte Flamme von Bashal'Aran aus.", completion = "Ihr habt unseren Dank. Es ist an der Zeit, die Vergangenheit hinter uns zu lassen und uns der Zukunft zu widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13563] = { id = 13563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Liebe", description = "Ich möchte Euch meinen Dank für unsere Rettung aussprechen. Man könnte behaupten, ich hätte Glück gehabt, doch meine geliebte Anaya ist schon lange tot. Ich bin einsam und in Schwierigkeiten und leider benötige ich schon wieder Eure Hilfe.\n\nNach meiner Rettung bin ich in den Wäldern von Dunkelküste umhergewandert und habe die Ruinen von Bashal'Aran entdeckt... und sah den Geist meiner geliebten Anaya.\n\nSie muss befreit werden, doch ich selbst bekomme es nicht übers Herz. Ihr Geist muss zerstört werden.", sourceObjective = "Befreit den Geist von Anaya Dämmerflucht und erhaltet ihren Anhänger.", progress = "Es ist mir irgendwie gelungen, nicht mit dem gleichen Gift in Berührung zu kommen wie all die anderen. Doch in gewissem Sinne beneide ich sie sogar... eine Ewigkeit in Einsamkeit zu verbringen erscheint kaum lebenswert.\n\nIch vermisse dich so sehr, Anaya.", completion = "Ich danke Euch, {name}. Vielleicht wäre es besser gewesen... wenn ich es selbst getan hätte. Doch selbst nach Tausenden von Jahren konnte ich die Hand nicht gegen sie erheben.\n\nIch bitte Euch, lasst mich nun allein in meiner Trauer...", sourceObjectiveStatus = "unverified-source-field" }
quests[13564] = { id = 13564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorener Freund", description = "Bitte helft mir... Ich kann mich kaum aufsetzen.\n\nMein Freund, ein Bär namens Grimmklaue, ist nicht hier. Ich habe ihn vorausgeschickt, um den Schildwachen unsere Ankunft anzukündigen, bevor wir Auberdine verließen, doch er kam nie an. Ich spürte bereits, dass etwas nicht in Ordnung war, als wir uns auf den Weg machten, aber durch die Evakuierung konnte ich der Angelegenheit nicht nachgehen.\n\nSollte er sich verletzt haben, so gibt es nur einen Ort, den er aufsuchen würde: das Welkende Dickicht nördlich von Auberdine, an der Straße südlich von hier. Bringt ihn sicher zu mir zurück... ich habe niemanden außer ihm.", sourceObjective = "Findet Grimmklaue.", completion = "Seid gegrüßt. Ihr scheint Interesse an meinem Freund zu haben. Ich nehme an, sein Freund Volcor hat Euch geschickt? Wenn er nicht selbst gekommen ist, so muss auch er verwundet sein. Ich hoffe, er wird bald gesunden.\n\nGrimmklaue ist zu schwer verletzt, um weit transportiert werden zu können, und er muss dringend behandelt werden. Ich fürchte, ich kann nicht zulassen, dass Ihr ihn mitnehmt, aber vielleicht könnt Ihr mir dabei helfen, mich um ihn zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13565] = { id = 13565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiten Grades", description = "Unbesonnene Gewalt können wir nicht gutheißen - das liegt nicht in unserer Natur. Doch mitunter bringt die Vermeidung von Kämpfen unübersehbare Folgen mit sich, wie in unserem Fall mit den Naga.\n\nAls die Erde in dieser Gegend brach, erschienen östlich von hier kleine Ruinen. Diese Ruinen waren einst die Heimat der Untertanen Königin Azsharas. Nun scheint es, als sei dieses Volk auf der Suche nach etwas zurückgekehrt.\n\nNehmt diese versteinerte Wurzel. Ihr könnt sie auf ihre Gefallenen anwenden und Ents zu Hilfe rufen. Kümmert Euch schleunig um sie und ihre Anführerin.", sourceObjective = "Benutzt die versteinerte Wurzel, ruft 6 siechende Ents und entledigt Euch Lady Janiras, der Anführerin der Naga.", completion = "Ich danke Euch, Verbündeter. Wir werden wachsamer sein, sollten sie wiederkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13566] = { id = 13566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materialien für das Ritual", description = "Während wir uns um Grimmklaue kümmern, möchte ich Euch bitten, kampflos von den Wildtieren ein paar Materialien für das Ritual zu sammeln.\n\nIch benötige Schnurrhaare eines Mondpirschers westlich von hier - geht zu den schlafenden Mondpirschern und versucht, ihnen die Haare auszureißen, und entfernt Euch, bevor sie aufwachen.\n\nIch brauche auch Haare der Rehe östlich von hier, aber meidet die Hirsche.\n\nUnd zu guter Letzt brauche ich das Fell der Bären beim Wasser nordöstlich von hier. Wartet, bis sie einen Fisch gefangen haben, besorgt die Fellprobe, und entfernt Euch von den Bären, bevor sie aufgegessen haben.\n\nBitte, fügt ihnen keine Schmerzen zu.", sourceObjective = "Besorgt 3 Schnurrhaare eines Mondpirschers, 3 Büschel gefleckter Rehhaare und 3 Proben Distelbärenfell.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe? Und bitte sagt mir, dass Ihr den Tieren keine Schmerzen zugefügt habt, um sie zu erhalten.", completion = "Diese Materialien sind perfekt. Sie sind die letzten Zutaten für einen speziellen Weihrauch, an dem ich arbeite. Ich werde es Euch gleich erklären - lasst mich die Zutaten nur schnell vermischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13567] = { id = 13567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Hirsches", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister verschreiben.\n\nWenn Ihr Euch mit dem großen Hirschgeist verbünden wollt, so bringt diesen Weihrauch zu den Wäldern nördlich von Bashal'Aran. Meditiert vor dem großen Geist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", sourceObjective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Hirschgeists einzuholen.", completion = "Ich sorge für mein Volk. Ich führe es nicht mit Gewalt, sondern mit Weisheit und Schnelligkeit. Weisheit leitet uns tiefer in die Wälder, wenn Gefahr droht, und Schnelligkeit sorgt dafür, dass unsere Feinde nur noch unsere Abwesenheit feststellen können.\n\nDank meiner Weisheit kann ich Eure wahren Absichten hinter der Bitte nach meinem Segen sehen und weiß, dass Ihr den Segen meiner Schnelligkeit verdient. Ihr werdet ihn erhalten, doch Ihr müsst Euch darüber im Klaren sein, dass die anderen Geister Euch nicht mehr willkommen heißen werden, sobald Ihr ihn habt. Überlegt Euch gut, ob dies Euren Wünschen entspricht, bevor ich Euch meinen Segen erteile.", sourceObjectiveStatus = "unverified-source-field" }
quests[13568] = { id = 13568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Mondpirschers", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister zuschreiben.\n\nWenn Ihr Euch mit dem großen Mondpirschergeist verbünden wollt, so bringt diesen Weihrauch in die Länder südlich der Ruinen von Lornesta. Meditiert vor dem großen Mondpirschergeist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", sourceObjective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Mondpirschergeists einzuholen.", completion = "Ich teile diese Wälder gerne und akzeptiere Nachtelfen in meiner Heimat - manchmal bezeichne ich sie sogar als Freunde. Auch wenn sie in letzter Zeit viel unter der Verderbnis gelitten haben, so kann ich doch in Euch die gleiche Stärke, Ehre und auch das Temperament sehen, das ich an ihnen schätze.\n\nWenn Ihr den Wert der Wildheit erkennt, die zur Bezwingung mancher Probleme wichtig ist, so bin ich bereit, Euch meinen Champion zu nennen. Ihr müsst jedoch wissen, dass Euch die anderen Geister nicht akzeptieren werden, wenn Ihr Euch mir verschreibt. Überlegt Euch diese Entscheidung gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[13569] = { id = 13569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bund des Rituales", description = "Ich werde mich um Grimmklaue kümmern, bis er sich vollständig erholt hat. Bald wird er bereit sein, in seine Heimat zurückzukehren. Ich habe eine weitere Aufgabe für Euch, während wir warten...vielmehr möchte ich Euch einen Gefallen tun, wenn Ihr dies wünscht.\n\nDie großen Geister der Wildtiere sind unter uns und warten auf Hilfe, um die Zerstörung aufzuhalten. Sie sind immer bei uns, auch jetzt, und mit den Materialien, die Ihr mir gebracht habt, kann ich Euch ermöglichen, sie zu sehen. Sprecht mit den Geistern, wählt einen von ihnen und kehrt mit dem Segen dieses Geistes zu mir zurück.", sourceObjective = "Atmet den Weihrauch vor Bewahrer Karithus ein und trefft eine Entscheidung zwischen dem Segen des großen Hirschgeistes, des großen Distelbärgeistes und des großen Mondpirschergeistes.\n\nNur einer der Geister kann Euch seinen Segen erteilen, also wählt weise.", completion = "Es ist vollbracht. Ihr habt den Segen eines der großen Geister erhalten und nun kann ich das Ritual mit Euch abschließen. Bitte haltet still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13570] = { id = 13570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Andenken an Auberdine", sourceObjective = "Ich möchte Euch meinen tiefsten Dank für Eure Hilfe aussprechen. In meiner Trauer habe ich Euch zuvor nicht die Dankbarkeit entgegengebracht, die Ihr verdient hättet. Ohne Euch wären wir jetzt wohl nicht hier.\n\nSeid Euch gewiss, dass Ihr hier immer Freunde haben werdet.\n\nUnd sorgt Euch nicht um meine Einsamkeit. Grimmklaue ist gute Gesellschaft und er bietet mir mehr Trost, als ich erwartet hätte.\n\nNehmt dies und unseren Segen, bis wir einander wiedersehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13571] = { id = 13571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletchers Fundbüro", sourceObjective = "Durch den Gestank nach etwas Abgestandenem und Ungewaschenem hindurch dringt Euch bekannter Geruch in die Nase! Es scheint, als wäre dieser einst so mächtige Abenteurer ganz verrückt nach Kungaloosh.\n\nAls Ihr durch die Gitterstäbe schaut, könnt Ihr gerade so eben das Rezept erkennen, das auf seinem Arm steht...", sourceObjectiveStatus = "unverified-source-field" }
quests[13572] = { id = 13572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadefeuerkohlenpfannen", description = "Die Satyrn aus Teufelswald haben angefangen, Hass und Verderbnis in unsere Länder zu bringen. Sie haben Sharax den Schänder geschickt, um Teile des Waldes zu unterwerfen, den wir Schwarzfelle unsere Heimat nennen.\n\nEr vergiftet nicht nur das Land, die Tiere und die Pflanzen, sondern hat auch überall im Dorf Jadefeuerkohlenpfannen aufgestellt, die ihm dabei helfen, Kontrolle über mein Volk zu erlangen. Die Kohlenpfannen zu zerstören, wird ihn allein nicht aufhalten können, aber es wird seinen Einfluss mindern, während wir mit dem Ältesten Brolg zusammen unsere Brüder befreien können.", sourceObjective = "Gren Fetzfell in der Schwarzfellfeste möchte, dass Ihr 8 Jadefeuerkohlenpfannen zerstört.", completion = "Ich danke Euch, {name}. Dank Euren Anstrengungen können wir vielleicht die übrigen Schwarzfelle retten.", sourceObjectiveStatus = "unverified-source-field" }
